<?php require_once __DIR__.'/../config/config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);$pdo->prepare('UPDATE admin_notifications SET is_read=1 WHERE id=?')->execute([$id]);flash('notice','Notification marked as read.');header('Location: notifications.php');exit;}$pageTitle='Notifications';$active='notifications';$rows=[];try{$rows=$pdo->query('SELECT * FROM admin_notifications ORDER BY created_at DESC LIMIT 200')->fetchAll();}catch(Throwable $e){}require __DIR__.'/_layout.php';?><section class="welcome-row"><div><p class="eyebrow">INBOX</p><h1>Studio <em>notifications.</em></h1><p class="muted">System notices and reminders stored in the database.</p></div></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>NOTICE</th><th>TYPE</th><th>DATE</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['title'])?></b><small><?=e($r['message']??'')?></small></td><td><?=e($r['severity'])?></td><td><?=e($r['created_at'])?></td><td><?=((int)$r['is_read']?'Read':'Unread')?></td><td><?php if(!(int)$r['is_read']):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-small">Mark read</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">No notifications recorded.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/_footer.php';?>